/**
 * Why an exchange with Prime failed, as the app reports it.
 */
sealed class LinkException: kotlin.Exception() {
    
    /**
     * The person stopped the exchange.
     */
    class Cancelled(
        ) : LinkException() {
        override val message
            get() = ""
    }
    
    /**
     * The transport failed.
     */
    class Failed(
        
        val `reason`: kotlin.String
        ) : LinkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LinkException> {
        override fun lift(error_buf: RustBuffer.ByValue): LinkException = FfiConverterTypeLinkError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLinkError : FfiConverterRustBuffer<LinkException> {
    override fun read(buf: ByteBuffer): LinkException {
        

        return when(buf.getInt()) {
            1 -> LinkException.Cancelled()
            2 -> LinkException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LinkException): ULong {
        return when(value) {
            is LinkException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LinkException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: LinkException, buf: ByteBuffer) {
        when(value) {
            is LinkException.Cancelled -> {
                buf.putInt(1)
                Unit
            }
            is LinkException.Failed -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * How a Lightning payment ended.
 */
sealed class Payment {
    
    /**
     * The gateway paid the invoice; the preimage, in hex, proves it.
     */
    data class Paid(
        val `preimage`: kotlin.String) : Payment()
        
    {
        

        companion object
    }
    
    /**
     * The gateway gave up and the funds came back, less fees. Prime signed the refund.
     */
    object Refunded : Payment()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePayment : FfiConverterRustBuffer<Payment>{
    override fun read(buf: ByteBuffer): Payment {
        return when(buf.getInt()) {
            1 -> Payment.Paid(
                FfiConverterString.read(buf),
                )
            2 -> Payment.Refunded
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Payment): ULong = when(value) {
        is Payment.Paid -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`preimage`)
            )
        }
        is Payment.Refunded -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: Payment, buf: ByteBuffer) {
        when(value) {
            is Payment.Paid -> {
                buf.putInt(1)
                FfiConverterString.write(value.`preimage`, buf)
                Unit
            }
            is Payment.Refunded -> {
                buf.putInt(2)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * How much each QR code shown to Prime carries. Denser codes mean fewer parts, and smaller
 * modules for Prime's camera to read. Low is the size of Prime's own codes and of the codes
 * Envoy shows Passport by default; Medium is the largest Envoy offers; High goes beyond that.
 */

enum class QrDensity {
    
    LOW,
    MEDIUM,
    HIGH;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeQrDensity: FfiConverterRustBuffer<QrDensity> {
    override fun read(buf: ByteBuffer) = try {
        QrDensity.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: QrDensity) = 4UL

    override fun write(value: QrDensity, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * Where reading Prime's answer stands after one more code.
 */
sealed class Scan {
    
    /**
     * More codes are needed; roughly this much has arrived, from 0 to 1.
     */
    data class Partial(
        val `progress`: kotlin.Double) : Scan()
        
    {
        

        companion object
    }
    
    /**
     * The whole answer.
     */
    data class Complete(
        val `answer`: kotlin.ByteArray) : Scan()
        
    {
        

        companion object
    }
    
    /**
     * The code is not part of an answer from Prime, or belongs to another answer.
     */
    data class Rejected(
        val `reason`: kotlin.String) : Scan()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeScan : FfiConverterRustBuffer<Scan>{
    override fun read(buf: ByteBuffer): Scan {
        return when(buf.getInt()) {
            1 -> Scan.Partial(
                FfiConverterDouble.read(buf),
                )
            2 -> Scan.Complete(
                FfiConverterByteArray.read(buf),
                )
            3 -> Scan.Rejected(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Scan): ULong = when(value) {
        is Scan.Partial -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`progress`)
            )
        }
        is Scan.Complete -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`answer`)
            )
        }
        is Scan.Rejected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: Scan, buf: ByteBuffer) {
        when(value) {
            is Scan.Partial -> {
                buf.putInt(1)
                FfiConverterDouble.write(value.`progress`, buf)
                Unit
            }
            is Scan.Complete -> {
                buf.putInt(2)
                FfiConverterByteArray.write(value.`answer`, buf)
                Unit
            }
            is Scan.Rejected -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Why a wallet call failed. Flat for the app: each exception carries the message to show.
 */
sealed class WalletException(message: String): kotlin.Exception(message) {
        
    /**
     * The wallet has not joined a federation yet.
     */
        class NotJoined(message: String) : WalletException(message)
        
    /**
     * The wallet already belongs to a federation.
     */
        class AlreadyJoined(message: String) : WalletException(message)
        
    /**
     * An invite code, token, invoice, address or amount the wallet cannot use.
     */
        class Invalid(message: String) : WalletException(message)
        
    /**
     * Prime refused, or the exchange with it failed or was cancelled.
     */
        class Prime(message: String) : WalletException(message)
        
    /**
     * The federation, the network or the phone's storage failed.
     */
        class Failed(message: String) : WalletException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WalletException> {
        override fun lift(error_buf: RustBuffer.ByValue): WalletException = FfiConverterTypeWalletError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeWalletError : FfiConverterRustBuffer<WalletException> {
    override fun read(buf: ByteBuffer): WalletException {
        
            return when(buf.getInt()) {
            1 -> WalletException.NotJoined(FfiConverterString.read(buf))
            2 -> WalletException.AlreadyJoined(FfiConverterString.read(buf))
            3 -> WalletException.Invalid(FfiConverterString.read(buf))
            4 -> WalletException.Prime(FfiConverterString.read(buf))
            5 -> WalletException.Failed(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: WalletException): ULong {
        return 4UL
    }

    override fun write(value: WalletException, buf: ByteBuffer) {
        when(value) {
            is WalletException.NotJoined -> {
                buf.putInt(1)
                Unit
            }
            is WalletException.AlreadyJoined -> {
                buf.putInt(2)
                Unit
            }
            is WalletException.Invalid -> {
                buf.putInt(3)
                Unit
            }
            is WalletException.Prime -> {
                buf.putInt(4)
                Unit
            }
            is WalletException.Failed -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




